package cn.local.gaokao;
import android.graphics.*;
import android.graphics.drawable.Drawable;
/** Small original line icons for the three persistent destinations. */
public final class UiIcon extends Drawable {
 final int kind,size;final Paint p=new Paint(3);
 UiIcon(int kind,int size,int color){this.kind=kind;this.size=size;p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);setBounds(0,0,size,size);}
 public int getIntrinsicWidth(){return size;}public int getIntrinsicHeight(){return size;}
 public void draw(Canvas c){c.save();c.translate(getBounds().left,getBounds().top);c.scale(getBounds().width()/28f,getBounds().height()/28f);if(kind==12){c.drawRoundRect(3,6,25,26,3,3,p);c.drawLine(3,12,25,12,p);c.drawLine(9,2,9,9,p);c.drawLine(19,2,19,9,p);c.drawLine(8,18,12,18,p);c.drawLine(16,18,20,18,p);c.drawLine(8,22,12,22,p);}else if(kind==0){Path path=new Path();path.moveTo(3,4);path.cubicTo(7,3,10,4,14,6);path.cubicTo(18,4,22,3,25,4);path.lineTo(25,23);path.cubicTo(20,22,17,23,14,25);path.cubicTo(10,23,7,22,3,23);path.close();c.drawPath(path,p);c.drawLine(14,6,14,25,p);}else if(kind==1){c.drawRoundRect(3,8,25,25,3,3,p);c.drawLine(6,4,22,4,p);c.drawLine(9,1,19,1,p);c.drawLine(11,17,17,17,p);}else if(kind==2){c.drawRoundRect(4,2,24,26,3,3,p);Path path=new Path();path.moveTo(8,17);path.lineTo(12,12);path.lineTo(16,15);path.lineTo(20,8);c.drawPath(path,p);c.drawLine(8,22,20,22,p);}else if(kind==4||kind==5||kind==11){Path path=new Path();if(kind==4){path.moveTo(6,10);path.lineTo(14,18);path.lineTo(22,10);}else if(kind==5){path.moveTo(18,5);path.lineTo(9,14);path.lineTo(18,23);}else{path.moveTo(7,7);path.lineTo(21,21);path.moveTo(21,7);path.lineTo(7,21);}c.drawPath(path,p);}else if(kind==6){p.setStrokeWidth(3.5f);c.drawLine(5,6,23,6,p);c.drawLine(5,14,17,14,p);c.drawLine(5,22,10,22,p);}else if(kind==7){p.setStrokeWidth(3);c.drawLine(4,4,4,24,p);c.drawLine(4,24,24,24,p);Path line=new Path();line.moveTo(9,17);line.lineTo(14,12);line.lineTo(18,13);line.lineTo(24,5);c.drawPath(line,p);}else if(kind==8||kind==9){p.setStrokeWidth(3);if(kind==9){p.setStyle(Paint.Style.FILL);c.drawCircle(14,14,11,p);p.setStyle(Paint.Style.STROKE);int color=p.getColor();p.setColor(Color.WHITE);c.drawLine(14,7,14,14,p);c.drawLine(14,14,19,18,p);p.setColor(color);}else{c.drawArc(3,3,25,25,-40,320,false,p);c.drawLine(14,6,11,14,p);c.drawLine(11,14,16,18,p);}}else{c.drawCircle(14,14,12,p);c.drawCircle(14,10,4,p);c.drawArc(6,15,22,29,200,140,false,p);}c.restore();}
 public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}
}
